 assert.equal(C.reorderList(a,'cars','cities',['cars','cities'],true),true);assert.deepEqual(plain(a.listOrder),['cities','places','cars']);assert.deepEqual(plain(a.listIds),['cities','cars']);assert.equal(JSON.stringify(a.lastResult),snapshot);assert.equal(JSON.stringify(a.lockedPicks),locks);assert.equal(JSON.stringify(a.drawCounts),counts);assert.equal(JSON.stringify(s.setups[1]),other);
 const restored=C.parseBackup(JSON.stringify(s));assert.deepEqual(plain(restored.setups[0].listOrder),['cities','places','cars']);C.selectList(restored.setups[0],'places',true);assert.deepEqual(plain(restored.setups[0].listIds),['cities','places','cars']);assert.equal(C.generate(restored,restored.setups[0],()=>0).picks[1].listId,'places');
