function linkedFixture(){const s=make();s.lists=[{id:'vehicles',name:'Vehicles',items:['Car','SUV','Bicycle'],links:[{value:'Car',listId:'car_models'},{value:'SUV',listId:'suv_models'}]},{id:'car_models',name:'Car models',items:['BMW M3','Porsche 911','Honda Civic']},{id:'suv_models',name:'SUV models',items:['Porsche Cayenne','Honda Passport']}];for(const a of s.setups){a.listOrder=s.lists.map(l=>l.id);a.listIds=['vehicles'];a.instructions='';}return s;}
function seededPicks(...indices){return length=>{assert.ok(indices.length,'unexpected random draw');const index=indices.shift();assert.ok(index<length,'test index outside pool');return index;};}
test('linked draws choose a category before a child and never cross categories',()=>{
 const s=linkedFixture(),a=s.setups[0];for(const [category,child,expected] of [[0,0,'Car, BMW M3'],[0,2,'Car, Honda Civic'],[1,0,'SUV, Porsche Cayenne'],[1,1,'SUV, Honda Passport']]){const bounds=[],r=C.generate(s,a,length=>{bounds.push(length);return bounds.length===1?category:child;});assert.equal(r.text,expected);assert.deepEqual(bounds,[3,s.lists[category+1].items.length]);assert.equal(r.picks.length,1);assert.equal(r.picks[0].child.listId,s.lists[category+1].id);}assert.equal(C.generate(s,a,seededPicks(2)).text,'Bicycle');
});
