function balancedFixture(){const s=linkedFixture();s.lists[0].items=['Car','SUV'];s.lists[1].items=Array.from({length:10},(_,i)=>'Car '+i);s.lists[2].items=Array.from({length:3},(_,i)=>'SUV '+i);return s;}
test('default and explicit Equal categories retain 50/50 category odds with unequal child counts',()=>{
 for(const mode of [undefined,'categories']){const s=balancedFixture();if(mode)s.lists[0].selectionMode=mode;for(let category=0;category<2;category++){const bounds=[];const r=C.generate(s,s.setups[0],n=>{bounds.push(n);return bounds.length===1?category:0;});assert.deepEqual(bounds,[2,category===0?10:3]);assert.equal(r.picks[0].value,category===0?'Car':'SUV');}}
});
test('Equal items gives each of 13 final vehicles exactly one unbiased integer outcome',()=>{
 const s=balancedFixture();s.lists[0].selectionMode='items';const outcomes=[];
 for(let ticket=0;ticket<13;ticket++){let calls=0;const r=C.generate(s,s.setups[0],n=>{calls++;assert.equal(n,13);return ticket;});assert.equal(calls,1);outcomes.push(r.text);}
 assert.deepEqual(outcomes,[...s.lists[1].items.map(x=>'Car, '+x),...s.lists[2].items.map(x=>'SUV, '+x)]);assert.equal(new Set(outcomes).size,13);
 s.setups[0].includeListNames=true;assert.equal(C.generate(s,s.setups[0],()=>12).text,'Vehicles: SUV, SUV 2');
});
test('Equal items counts distinct pairs, handles plain entries, and counts shared children per category',()=>{
 const s=linkedFixture();s.lists[0].selectionMode='items';s.lists[0].items=['Car','Car','SUV','Bicycle','Bicycle','Coupe'];s.lists[0].links.push({value:'Coupe',listId:'car_models'});s.lists[1].items=['BMW','BMW','Honda'];s.lists[2].items=['BMW','BMW'];
 const outcomes=Array.from({length:6},(_,i)=>C.generate(s,s.setups[0],n=>{assert.equal(n,6);return i;}).text);
 assert.deepEqual(outcomes,['Car, BMW','Car, Honda','SUV, BMW','Bicycle','Coupe, BMW','Coupe, Honda']);
 // Reverting the mode restores intentional duplicate weighting.
 s.lists[0].selectionMode='categories';const bounds=[];C.generate(s,s.setups[0],n=>{bounds.push(n);return 0;});assert.deepEqual(bounds,[6,3]);
});
test('Equal items retains distinct categories and full locked pairs for multiple draws',()=>{
 const s=balancedFixture(),a=s.setups[0];s.lists[0].selectionMode='items';C.setDrawCount(a,'vehicles',2);let calls=0;const bounds=[];
 const r=C.generate(s,a,n=>{bounds.push(n);return calls++===0?12:9;});assert.deepEqual(bounds,[13,10]);assert.deepEqual(plain(r.picks.map(p=>p.value)),['SUV','Car']);assert.equal(r.picks[1].child.value,'Car 9');C.toggleLock(s,a,r.picks[1]);
 const next=C.generate(s,a,n=>{assert.equal(n,3);return 0;});assert.equal(next.picks[0].child.value,'SUV 0');assert.deepEqual(plain(next.picks[1]),plain(r.picks[1]));C.toggleLock(s,a,next.picks[0]);assert.deepEqual(plain(C.generate(s,a,()=>{throw Error('All picks are locked');}).picks),plain(next.picks));
 s.lists[0].selectionMode='categories';C.reconcileLocks(s);assert.equal(a.lockedPicks.length,2);C.setDrawCount(a,'vehicles',3);assert.throws(()=>C.generate(s,a),/Lower its Draw count/);
});
test('Equal items recalculates after child edits without rewriting saved output or favorites',()=>{
 const s=balancedFixture(),a=s.setups[0];s.lists[0].selectionMode='items';C.recordResult(s,a,C.generate(s,a,()=>12));C.toggleFavorite(s,a.lastResult,a.name);const before=JSON.stringify([a.lastResult,s.favorites,s.recentResults]);
 s.lists[2].items.push('SUV 3');assert.equal(C.generate(s,a,n=>{assert.equal(n,14);return 13;}).text,'SUV, SUV 3');s.lists[1].items=['Car 0'];assert.equal(C.generate(s,a,n=>{assert.equal(n,5);return 4;}).text,'SUV, SUV 3');assert.equal(JSON.stringify([a.lastResult,s.favorites,s.recentResults]),before);
});
test('schema 8 saves both selection modes and upgrades older backups to the existing default',()=>{
 const s=linkedFixture();s.lists[0].selectionMode='items';const text=JSON.stringify(s);assert.equal(C.VERSION,8);assert.equal(C.parseBackup(text).lists[0].selectionMode,'items');assert.equal(JSON.stringify(s),text);s.lists[0].selectionMode='categories';assert.equal(C.validate(s).lists[0].selectionMode,'categories');
 const old=linkedFixture();old.version=7;const original=JSON.stringify(old),m=C.parseBackup(original);assert.equal(m.version,8);assert.equal(m.lists[0].selectionMode,undefined);m.version=7;assert.deepEqual(plain(m),old);assert.equal(JSON.stringify(old),original);
 for(const invalid of [null,true,1,{},[], 'equal','', 'ITEMS']){s.lists[0].selectionMode=invalid;const before=JSON.stringify(s);assert.throws(()=>C.parseBackup(before));assert.equal(JSON.stringify(s),before);}s.version=9;assert.throws(()=>C.validate(s));
});
test('backup merge keeps independent parent modes and remaps linked locks',()=>{
 const current=linkedFixture(),incoming=balancedFixture();current.lists[0].selectionMode='categories';incoming.lists[0].selectionMode='items';const a=incoming.setups[0];C.recordResult(incoming,a,C.generate(incoming,a,()=>12));C.toggleLock(incoming,a,a.lastResult.picks[0]);C.toggleFavorite(incoming,a.lastResult,a.name);const m=C.merge(current,incoming),setup=m.setups.find(x=>x.id===m.activeSetupId),parent=m.lists.find(x=>x.id===setup.listIds[0]);
 assert.equal(m.lists[0].selectionMode,'categories');assert.equal(parent.selectionMode,'items');assert.notEqual(parent.id,'vehicles');assert.equal(setup.lockedPicks[0].child.listId,parent.links.find(l=>l.value==='SUV').listId);assert.equal(C.generate(m,setup,()=>{throw Error('Locked');}).text,'SUV, SUV 2');assert.equal(C.validate(m).lists.find(l=>l.id===parent.id).selectionMode,'items');assert.equal(m.favorites[0].text,'SUV, SUV 2');
});
test('Equal items supports 2.5 billion virtual pairs without flattening the lists',()=>{
 const s=linkedFixture(),parent=s.lists[0];parent.selectionMode='items';parent.items=Array.from({length:50000},(_,i)=>'Category '+i);parent.links=parent.items.map(value=>({value,listId:'car_models'}));s.lists[1].items=Array.from({length:50000},(_,i)=>'Model '+i);
 const r=C.generate(s,s.setups[0],n=>{assert.equal(n,2500000000);return n-1;});assert.equal(r.text,'Category 49999, Model 49999');
});
test('Equal items rejects broken links, empty children and invalid randomness without changing state',()=>{
 const s=balancedFixture();s.lists[0].selectionMode='items';const before=JSON.stringify(s);for(const value of [-1,13,0.5,NaN])assert.throws(()=>C.generate(s,s.setups[0],()=>value),/Random source/);assert.equal(JSON.stringify(s),before);s.lists[2].items=[];assert.throws(()=>C.generate(s,s.setups[0],()=>0),/empty/);s.lists.pop();assert.throws(()=>C.generate(s,s.setups[0],()=>0),/missing/);
});

